#include <assert.h>
#include <errno.h>
#include <stdio.h>
#include "../transport/fh8626_http_client.h"
int main(void){struct fh_http_client slow,fast;const struct fh_http_packet*p;char key='K',data[3]={'D','D','D'};fh_http_client_init(&slow,1,1,3,100);fh_http_client_init(&fast,2,1,16,100);assert(fh_http_client_set_generation(&slow,5)==0);assert(fh_http_client_set_generation(&fast,5)==0);assert(fh_http_client_accept_header(&slow,5,10)==0);assert(fh_http_client_accept_header(&fast,5,10)==0);assert(fh_http_client_enqueue(&slow,FH_HTTP_VIDEO,5,0,0,data,1,NULL)==-EAGAIN);assert(fh_http_client_enqueue(&slow,FH_HTTP_VIDEO,5,1,0,&key,1,NULL)==0);assert(fh_http_client_take(&slow,50,&p)==1);assert(fh_http_client_send_result(&slow,0)==0&&!slow.need_idr);assert(fh_http_client_enqueue(&slow,FH_HTTP_VIDEO,5,0,60,data,3,NULL)==0);assert(fh_http_client_enqueue(&slow,FH_HTTP_VIDEO,5,0,61,data,1,NULL)==-ENOSPC&&slow.need_idr);assert(fh_http_client_enqueue(&fast,FH_HTTP_VIDEO,5,1,60,&key,1,NULL)==0);assert(fh_http_client_take(&fast,70,&p)==1&&fh_http_client_send_result(&fast,0)==0&&!fast.need_idr);/* slow client's loss did not affect fast */assert(fh_http_client_take(&slow,160,&p)==-ETIMEDOUT&&slow.state==FH_HTTP_FAILED);assert(fast.state==FH_HTTP_READY);assert(fh_http_client_cancel(&slow)==0&&slow.state==FH_HTTP_CLOSED);assert(fh_http_client_set_generation(&fast,6)==0&&!fast.header_ready&&fast.need_idr&&fast.count==0);assert(fh_http_client_begin_close(&fast)==0&&fast.state==FH_HTTP_CLOSING);assert(fh_http_client_cancel(&fast)==0&&fast.state==FH_HTTP_CLOSED);puts("test_http_client: PASS");return 0;}
